// ---- 查找辅助 ----
[[nodiscard]] constexpr std::string_view BulletKindFrame(BulletKind kind) {
    for (const auto& item : kBulletKinds) {
        if (item.kind == kind) {
            return item.frame;
        }
    }
    return {};
}

[[nodiscard]] constexpr std::string_view BulletKindAtlas(BulletKind kind) {
    for (const auto& item : kBulletKinds) {
        if (item.kind == kind) {
            return item.atlas;
        }
    }
    return {};
}

[[nodiscard]] constexpr std::string_view BulletKindSpecies(BulletKind kind) {
    for (const auto& item : kBulletKinds) {
        if (item.kind == kind) {
            return item.species;
        }
    }
    return {};
}

[[nodiscard]] constexpr BulletMotionFamily BulletMotionFamilyOf(BulletMotion motion) {
    for (const auto& item : kBulletMotions) {
        if (item.motion == motion) {
            return item.family;
        }
    }
    return BulletMotionFamily::kUnspecified;
}

// ---- POD 结构 ----
struct DanmakuFieldSpec {
    std::uint32_t width = kDanmakuPlayfieldWidth;
    std::uint32_t height = kDanmakuPlayfieldHeight;
    std::uint32_t half_width = kDanmakuPlayfieldHalfWidth;
    std::uint32_t half_height = kDanmakuPlayfieldHalfHeight;
    std::uint32_t tick_rate_hz = kDanmakuTickRateHz;
};

// 严格对应原版 96 字节 Enemy::CreateBulletCommand（28 字段，字段偏移与原版一致）。
// spawn_x/spawn_y == -1.0f 为哨兵（跟随发射者坐标）；角度单位=度。
struct BulletSpawnCommand {
    std::int32_t bullet_type = 0;      // +0  BulletKind 值
    std::int32_t frame_index = 0;      // +4
    float spawn_x = -1.0f;             // +8
    float spawn_y = -1.0f;             // +12
    std::uint8_t flag16 = 0;           // +16
    std::uint8_t _pad17[3] = {0, 0, 0};// +17..19
    float base_angle_deg = 0.0f;       // +20
    float f24 = 0.0f;                  // +24
    float f28 = 0.0f;                  // +28
    float f32 = 0.0f;                  // +32
    float f36 = 0.0f;                  // +36
    float f40 = 0.0f;                  // +40
    std::int16_t count = 0;            // +44 本次发射数量（0 -> 直接返回）
    std::int16_t _pad46 = 0;           // +46
    float spread_or_speed = 0.0f;      // +48 张角/速度
    std::int16_t s52 = 0;              // +52
    std::int16_t s54 = 0;              // +54
    std::int16_t s56 = 0;              // +56
    std::int16_t _pad58 = 0;           // +58
    float f60 = 0.0f;                  // +60
    float f64 = 0.0f;                  // +64
    float f68 = 0.0f;                  // +68
    float f72 = 0.0f;                  // +72
    float f76 = 0.0f;                  // +76
    float f80 = 0.0f;                  // +80
    std::int16_t s84 = 0;              // +84
    std::int16_t s86 = 0;              // +86
    std::int16_t s88 = 0;              // +88
    std::int16_t s90 = 0;              // +90
    std::int16_t s92 = 0;              // +92
    std::int16_t s94 = 0;              // +94
};
static_assert(sizeof(BulletSpawnCommand) == 96, "CreateBulletCommand must be 96 bytes");
static_assert(offsetof(BulletSpawnCommand, base_angle_deg) == 20, "layout drift at +20");
static_assert(offsetof(BulletSpawnCommand, count) == 44, "layout drift at +44");
static_assert(offsetof(BulletSpawnCommand, s94) == 94, "layout drift at +94");

// 运行期子弹状态（服务端权威；坐标/速度 = 整数 milli，1/1000 px）。
struct DanmakuBulletState {
    std::string_view bullet_id;
    BulletKind bullet_kind = BulletKind::kUnspecified;
    BulletMotion motion = BulletMotion::kFunc00;
    std::int32_t x_milli = 0;
    std::int32_t y_milli = 0;
    std::int32_t vx_milli = 0;
    std::int32_t vy_milli = 0;
    std::uint32_t life_ticks = 0;
    std::uint32_t radius_milli = 0;
    std::uint32_t age_ticks = 0;
    std::uint32_t func_state = 0;   // 原版 +0x5B4 状态号
    float angle_deg = 0.0f;
    std::string_view owner_enemy_id;
};

// Boss 时间线的一个构造批次（setBossBullet* 内 frame % period == offset 的一个块）。
struct DanmakuTimelineEntry {
    std::uint32_t phase = 0;
    std::uint32_t sub_phase = 0;
    std::uint32_t sub_phase_2 = 0;
    std::uint32_t period_ticks = 0;
    std::uint32_t phase_offset = 0;
    std::uint32_t node_size_bytes = 0;
    std::uint32_t bullet_count = 0;
    std::uint32_t pattern_node_id = 0;
    float base_angle_deg = 0.0f;
    float spread_deg = 0.0f;
    BulletKind bullet_kind = BulletKind::kUnspecified;
    BulletMotion motion = BulletMotion::kFunc00;
    std::uint32_t sound_effect_id = 0;
    std::string_view angle_expr;
    std::string_view offset_expr;
};

